const _aaT=(ic,lb,v,rk,un,cls)=>`<div class="st-aa-tile"><span class="t-k">${ic}${lb}</span><b class="t-v ${cls}">${v}</b><span class="t-f"><span class="t-r">${rk}</span><span class="t-u">${[1,2,3,4].map(n=>`<i class="${n<=un?cls:''}"></i>`).join('')}</span></span></div>`;
/* Guete statt blosser Staerke: der Rang entscheidet, wie viele Punkte leuchten —
   Platz 1–25 % der Klasse vier Punkte, 26–50 % drei, 51–75 % zwei, darunter eins.
   Damit zaehlt bei Kosten und Ausfuehrlichkeit automatisch das Gegenteil: niedrig
   ist besser. Ohne Rang gilt die Einheiten-Zahl der Quelle, passend herumgedreht. */
const _aaG=(m,invert)=>{ if(m.rank){ const t=m.rank.match(/#?(\d+)\/(\d+)/);
    if(t){ const p=t[1]/t[2]; return p<=.25?4:p<=.5?3:p<=.75?2:1; } }
  const u=+m.u||0; return invert?5-u:u; };
const _aaCls=g=>g>=4?'gut':g==3?'mid':'wenig';
if(A.intel){const g=_aaG(A.intel,false);h+=_aaT(_IC.brain,'Intelligenz',A.intel.v,A.intel.rank||'',g,_aaCls(g));}
if(A.speed){const g=_aaG(A.speed,false);h+=_aaT(_IC.fast,'Tempo',A.speed.v,A.speed.rank||'',g,_aaCls(g));}
if(A.cost){const g=_aaG(A.cost,true);h+=_aaT(_IC.coins,'Kosten',A.cost.v,A.cost.rank||'',g,_aaCls(g));}
if(A.verb){const g=_aaG(A.verb,true);h+=_aaT(_IC.chat,'Ausführlichkeit',A.verb.v,A.verb.rank||'',g,_aaCls(g));}

